package uk.ac.ravensbourne.casevault.web;
import jakarta.persistence.OptimisticLockException; import jakarta.servlet.http.HttpServletResponse; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Controller; import org.springframework.web.*; import org.springframework.web.bind.MissingServletRequestParameterException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException; import org.springframework.web.multipart.MaxUploadSizeExceededException; import org.springframework.web.servlet.NoHandlerFoundException; import org.springframework.web.servlet.resource.NoResourceFoundException; import uk.ac.ravensbourne.casevault.service.CaseNotFoundException;
@ControllerAdvice public class CaseExceptionAdvice { @ExceptionHandler(OptimisticLockException.class) String conflict(){return "case-conflict";} @ExceptionHandler(HttpRequestMethodNotSupportedException.class) @ResponseStatus(HttpStatus.METHOD_NOT_ALLOWED) String method(HttpRequestMethodNotSupportedException e,HttpServletResponse r){if(e.getSupportedHttpMethods()!=null)r.setHeader("Allow",String.join(", ",e.getSupportedHttpMethods().stream().map(HttpMethod::name).toList()));return "error";} @ExceptionHandler(HttpMediaTypeNotSupportedException.class) @ResponseStatus(HttpStatus.UNSUPPORTED_MEDIA_TYPE) String media(){return "error";} @ExceptionHandler({MissingServletRequestParameterException.class,MethodArgumentTypeMismatchException.class,MethodArgumentNotValidException.class,HttpMessageNotReadableException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) String bad(){return "error";} @ExceptionHandler({NoResourceFoundException.class,NoHandlerFoundException.class,IllegalArgumentException.class,CaseNotFoundException.class}) @ResponseStatus(HttpStatus.NOT_FOUND) String missing(){return "error";} @ExceptionHandler(AccessDeniedException.class) @ResponseStatus(HttpStatus.FORBIDDEN) String denied(){return "error";} @ExceptionHandler(MaxUploadSizeExceededException.class) @ResponseStatus(HttpStatus.PAYLOAD_TOO_LARGE) String large(){return "error";} @ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) String unexpected(){return "error";} }
